body {
  text-rendering: optimizeLegibility; /* Balances speed and legibility, enabling advanced typographic features */
  -webkit-font-smoothing: antialiased; /* For WebKit/Blink browsers to render text with anti-aliasing */
  -moz-osx-font-smoothing: grayscale; /* For macOS Firefox, making text lighter and sharper */
  /* font-smooth: antialiased; /* Older Firefox support, generally superseded by -moz-osx-font-smoothing */
}
